acceptance.check:
python3 -c "from rt import retry
c = [0]
def g():
    c[0] += 1
    raise KeyError(c[0])
try:
    retry(g, 3)
except KeyError as e:
    assert c[0] == 3 and e.args[0] == 3
else:
    raise SystemExit(1)"

python3 -c "from rt import retry
c = [0]
def h():
    c[0] += 1
try:
    retry(h, 0)
except ValueError:
    assert c[0] == 0
else:
    raise SystemExit(1)"

